template <class T> class CowPtr {
    std::shared_ptr<T> sp_;
    void detach() {                       /* clone before the first write */
        if (sp_ && !sp_.unique()) sp_ = std::make_shared<T>(*sp_);
    }
public:
    const T& operator*() const { return *sp_; }
    T& operator*() { detach(); return *sp_; }   /* mutating access detaches */
};

