class Body { mutable unsigned refs_ = 1; /* payload ... */ };
class Handle {                        /* one pointer, no control block */
    Body* b_;
    void detach() { if (b_->refs_ > 1) { --b_->refs_; b_ = new Body(*b_); } }
public:
    Handle(const Handle& o) : b_(o.b_) { ++b_->refs_; }
    ~Handle() { if (--b_->refs_ == 0) delete b_; }
};
